const refsRaw=J(path.join(RES,"paper/references.json"));
const newRefs=["[27] Muggeo VMR. Estimating regression models with unknown break-points. Statistics in Medicine. 2003;22(19):3055-3071.","[28] Baker JW. Efficient analytical fragility function fitting using dynamic structural analysis. Earthquake Spectra. 2015;31(1):579-599.","[29] Cameron AC, Gelbach JB, Miller DL. Robust inference with multiway clustering. Journal of Business & Economic Statistics. 2011;29(2):238-249.","[30] Porter K, Kennedy R, Bachman R. Creating fragility functions for performance-based earthquake engineering. Earthquake Spectra. 2007;23(2):471-489."];
const refPars=[...refsRaw,...newRefs].map(r=>new Paragraph({spacing:{after:80},children:[new TextRun({text:r,size:18})]}));

const numbering={config:[{reference:"bul",levels:[{level:0,format:LevelFormat.BULLET,text:"•",alignment:AlignmentType.LEFT,style:{paragraph:{indent:{left:480,hanging:240}}}}]}]};
